MOD = 10**9 + 7

def modinv(a, m):
    return pow(a, m - 2, m)

def dfs(node, graph, visited):
    visited[node] = True
    component_size = 1
    for neighbor in graph[node]:
        if not visited[neighbor]:
            component_size += dfs(neighbor, graph, visited)
    return component_size

def main():
    n, m = map(int, input().split())
    graph = [[] for _ in range(n + 1)]
    for _ in range(m):
        u, v = map(int, input().split())
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * (n + 1)
    components = []
    for i in range(1, n + 1):
        if not visited[i]:
            components.append(dfs(i, graph, visited))

    expected_value = 0
    for component_size in components:
        expected_value += (1 - (1 / (2 ** component_size)))

    expected_value /= n

    variance = (expected_value * (1 - expected_value)) % MOD
    print(variance)

if __name__ == "__main__":
    main()
